    "shortDescription": "Siebzehn Tage und sechzehn Nächte mit einer Mischung aus kulturellen Sehenswürdigkeiten, Berglandschaften, Tierwelt und Stränden im Süden.",
    "overview": "Erkunden Sie Habarana, Sigiriya, Hiriwadunna und Minneriya, einschließlich einer Ballonfahrt und eines Besuchs in Anuradhapura. Entdecken Sie den Höhlentempel von Dambulla, den Zahntempel in Kandy, eine kulturelle Vorführung, den Ambuluwawa-Turm und den Königlichen Botanischen Garten. Weiter geht es über Nuwara Eliya zu den Ramboda-Wasserfällen, dem Gregory-See und einer Erdbeerfarm, anschließend nach Ella zur Neun-Bögen-Brücke, zum Mini-Adam’s Peak und zu den Ravana-Wasserfällen. Im südlichen Teil stehen der Yala-Nationalpark, Mirissa, das niederländische Fort in Galle, die Meeresschildkröten-Aufzuchtstation in Kosgoda und eine Sonnenuntergangsfahrt in Bentota auf dem Programm. Zum Abschluss stehen eine Stadtrundfahrt durch Colombo, Shopping und Streetfood auf dem Programm.",
